for c in range(10,22): G[22][c]=3
src=[row[:] for row in G]
for r in range(R):
    cs=[c for c,v in enumerate(src[r]) if v==3]
    if cs:
        for c in range(min(cs),max(cs)+1):
            if G[r][c]==1:G[r][c]=2
for c in range(C):
    rs=[r for r in range(R) if src[r][c]==3]
    if rs:
        for r in range(min(rs),max(rs)+1):
            if G[r][c]==1:G[r][c]=2
assert len(G)==29 and all(len(row)==23 for row in G)
print('non-background rows:')
for r,row in enumerate(G):
 if any(x!=1 for x in row):print(r+1,''.join(map(str,row)))
print(json.dumps(G,separators=(',',':')))
